/bin/bash -lc 'api_key_file="$GALAXY_API_KEY_FILE"; api_key="[REDACTED CREDENTIAL]"$api_key_file")"; for q in FIMO MAST "motif" "meme2meme"; do curl -sS --get -H "x-api-key: $api_key" --data-urlencode "q=$q" "$GALAXY_URL/api/tools" | python3 -c '"'import json,sys; d=json.load(sys.stdin); out=[]
for s in d:
  for x in s.get(\"elems\",[]):
    if x.get(\"model_class\")==\"Tool\": out.append((x.get(\"name\"),x.get(\"id\")))
print(\"\\n\".join(f\"{a}\\t{b}\" for a,b in out))' | head -80; done"

/bin/bash -lc 'api_key_file="$GALAXY_API_KEY_FILE"; api_key="[REDACTED CREDENTIAL]"$api_key_file")"; for q in FIMO MAST motif meme2meme; do echo "QUERY=$q"; curl -sS --get -H "x-api-key: $api_key" --data-urlencode "q=$q" "$GALAXY_URL/api/tools" | python3 -c '"'import json,sys; d=json.load(sys.stdin)
for x in d:
 print(f\"{x.get(\\\"name\\\")}\\t{x.get(\\\"id\\\")}\")' | head -80; done"

/bin/bash -lc 'api_key_file="$GALAXY_API_KEY_FILE"; api_key="[REDACTED CREDENTIAL]"$api_key_file")"; for q in FIMO MAST motif meme2meme; do echo "QUERY=$q"; curl -sS --get -H "x-api-key: $api_key" --data-urlencode "q=$q" "$GALAXY_URL/api/tools" | python3 -c '"'import json,sys; d=json.load(sys.stdin)
for x in d:
 print(\"{}\\t{}\".format(x.get(\"name\"),x.get(\"id\")))' | head -80; done"
